// Some portions generated by Claude
// The small exploration graph behind the user's layout reports: four people of class Person, an organization with
// three products, a city in a country, every resource labelled. Synthetic data, not a private query result.
import { RDF_TYPE } from '../../../../main/frontend/graph-explorer/graph-canvas-scope.ts';
import { sparqlNodeId } from '../../../../main/frontend/graph-explorer/rdf-terms.ts';

export const EX = 'http://example.org/';
export const iri = (name) => EX + name;
export const literalId = (value) => sparqlNodeId({ type: 'literal', value });

const PEOPLE = ['Alice', 'Bob', 'Carol', 'Dave'];
const LABELLED = ['Alice', 'Bob', 'Carol', 'Dave', 'Acme', 'Oslo', 'Widget', 'Gadget', 'Gizmo', 'Norway'];
const CLASS_OF = { Alice: 'Person', Bob: 'Person', Carol: 'Person', Dave: 'Person', Acme: 'Organization', Oslo: 'City' };

function resource(name) {
  const cls = CLASS_OF[name];
  return { id: iri(name), label: name, kind: 'iri', ...(cls ? { types: [{ id: iri(cls), label: cls }] } : {}) };
}
function statement(subject, predicate, object) {
  return { id: `${subject}|${predicate}|${object}`, source: subject, target: object, predicate, label: predicate.replace(EX, '').replace(RDF_TYPE, 'type') };
}

/** 23 nodes with Values on; 10 resources with Values off (`canvasGraph(graph, false)`). */
export function demoGraph() {
  const nodes = [
    ...['Alice', 'Bob', 'Carol', 'Dave', 'Acme', 'Oslo', 'Widget', 'Gadget', 'Gizmo', 'Norway', 'Person', 'Organization', 'City'].map(resource),
    ...LABELLED.map((name) => ({ id: literalId(name), label: name, kind: 'literal' })),
  ];
  const edges = [
    statement(iri('Alice'), iri('knows'), iri('Bob')),
    statement(iri('Alice'), iri('knows'), iri('Carol')),
    statement(iri('Alice'), iri('worksFor'), iri('Acme')),
    statement(iri('Bob'), iri('worksFor'), iri('Acme')),
    statement(iri('Bob'), iri('knows'), iri('Dave')),
    statement(iri('Carol'), iri('livesIn'), iri('Oslo')),
    statement(iri('Acme'), iri('locatedIn'), iri('Oslo')),
    statement(iri('Acme'), iri('makes'), iri('Widget')),
    statement(iri('Acme'), iri('makes'), iri('Gadget')),
    statement(iri('Acme'), iri('makes'), iri('Gizmo')),
    statement(iri('Oslo'), iri('country'), iri('Norway')),
    ...PEOPLE.map((name) => statement(iri(name), RDF_TYPE, iri('Person'))),
    statement(iri('Acme'), RDF_TYPE, iri('Organization')),
    statement(iri('Oslo'), RDF_TYPE, iri('City')),
    ...LABELLED.map((name) => statement(iri(name), iri('label'), literalId(name))),
  ];
  return { nodes, edges, revision: 1 };
}

/** Card centres of the ten resources in the user's "terrible curved lines" export (Values off, Square layout). */
export const BAD_EXPORT_CENTERS = {
  Alice: { x: 420.6, y: 144.7 }, Bob: { x: 748.7, y: 68.3 }, Carol: { x: 260.6, y: 144.7 }, Acme: { x: 420.6, y: 226.7 },
  Dave: { x: 908.7, y: 68.3 }, Oslo: { x: 100.6, y: 226.7 }, Widget: { x: 902, y: 146.3 }, Gadget: { x: 748.7, y: 150.3 },
  Gizmo: { x: 260.6, y: 226.7 }, Norway: { x: 100.6, y: 144.7 },
};

/** The demo graph with the ten resources placed as in the bad export and every hidden node at `hiddenAt(name)`. */
export function badExportGraph(hiddenAt = () => ({ x: 0, y: 0 })) {
  const graph = demoGraph();
  return {
    ...graph,
    nodes: graph.nodes.map((node) => ({ ...node, ...(BAD_EXPORT_CENTERS[node.label] && node.kind === 'iri' ? BAD_EXPORT_CENTERS[node.label] : hiddenAt(node.label, node.kind)) })),
  };
}
